    "regionLabels": { "north": "North", "south": "South", "east": "East", "west": "West" },
    "statusLabels": { "scheduled": "Scheduled", "en-route": "En route", "on-site": "On site", "done": "Done", "overdue": "Overdue" }
  }
}
